from pathlib import Path
import os,subprocess,tempfile,hashlib,json
p=Path("/home/appontrack/public_html/saas/mobile/contacts_api.php")
assert os.getuid()==2379 and p.parent.is_dir() and not p.is_symlink()
source="<?php
declare(strict_types=1);
require __DIR__.'/common.php';
require __DIR__.'/pilot_workspace.php';
mobile_require_device();
if($_SERVER['REQUEST_METHOD']==='GET') {
    $rows=array_slice(array_reverse(pilot_read('contacts')),0,200);
    $contacts=[];
    foreach($rows as $row) {
        $contacts[]=['id'=>(string)$row['id'],'name'=>(string)$row['name'],
            'phone'=>(string)$row['phone'],'do_not_call'=>!empty($row['do_not_call'])];
    }
    mobile_json(['ok'=>true,'contacts'=>$contacts,'total'=>count(pilot_read('contacts'))]);
}
if($_SERVER['REQUEST_METHOD']!=='POST')mobile_json(['ok'=>false,'error'=>'method_not_allowed'],405);
$raw=(string)file_get_contents('php://input');
if(strlen($raw)>1024)mobile_json(['ok'=>false,'error'=>'too_large'],413);
$data=json_decode($raw,true);
if(!is_array($data)||($data['confirmed']??false)!==true||
    !is_bool($data['blocked']??null)||
    !preg_match('/^[a-f0-9]{24}$/D',(string)($data['id']??'')))
    mobile_json(['ok'=>false,'error'=>'invalid_request'],422);
try {
    $found=pilot_dnc((string)$data['id'],$data['blocked']);
    if(!$found)mobile_json(['ok'=>false,'error'=>'not_found'],404);
    mobile_json(['ok'=>true,'updated'=>true]);
} catch(Throwable $e) {
    mobile_json(['ok'=>false,'error'=>'storage_unavailable'],503);
}
".encode("utf-8")
if p.exists():assert hashlib.sha256(p.read_bytes()).digest()==hashlib.sha256(source).digest(),"Unexpected live file"
else:
 with tempfile.NamedTemporaryFile(prefix=".contacts-api-",dir=str(p.parent),delete=False) as f:
  staged=f.name;f.write(source)
 try:
  lint=subprocess.run(["/usr/local/bin/php","-l",staged],capture_output=True,text=True,timeout=8)
  assert lint.returncode==0,lint.stderr
  os.chmod(staged,0o644);os.replace(staged,str(p))
 finally:
  if os.path.exists(staged):os.unlink(staged)
lint=subprocess.run(["/usr/local/bin/php","-l",str(p)],capture_output=True,text=True,timeout=8)
assert lint.returncode==0,lint.stderr
print(json.dumps({"status":"PASS","sha256":hashlib.sha256(p.read_bytes()).hexdigest()}))
